// PACKING_BULK_PREPARE - Guard: job_id (digits), session tenant
const prepareGuard = function prepareGuard(input) {
  const s = (v) => (v === undefined || v === null ? "" : String(v)).trim();
  const jobId = s(input.jobId);
  const tenantId = s(input.systemTenantId);
  const bad = (why) => ({ route: "REJECT", jobId: "0", tenantId: "0", result_code: "PK_INVALID_DATA", result_message: why });
  if (!/^[0-9]{1,20}$/.test(jobId)) return bad("job_id: digits only");
  if (!/^[0-9]{1,20}$/.test(tenantId)) return bad("no session tenant");
  return { route: "CONTINUE", jobId: jobId, tenantId: tenantId, result_code: "", result_message: "" };
};
const res = prepareGuard({ jobId: [{{workflowparams:job_id}}][0], systemTenantId: [{{system:tenantId}}][0] });
console.log("prepare guard", JSON.stringify(res));
return res;

// PACKING_BULK_PREPARE - Entry: the job must be a COMPLETE_PACKING job the worker holds (VALIDATING under a live lease);
// its request -> the ids the set-based reads need. A request that cannot be read fails the job.
const prepareEntry = function prepareEntry(guard, rows) {
  const s = (v) => (v === undefined || v === null ? "" : String(v)).trim();
  const ID = /^[0-9]{1,20}$/;
  const job = (Array.isArray(rows) ? rows : rows ? [rows] : []).filter((r) => r && s(r.id))[0] || null;
  const base = { route: "NOOP", jobId: guard.jobId, tenantId: guard.tenantId, organizationId: "0", plantId: "0", packingId: "0", gdId: "0", requestedBy: "", rowVersion: 0, dbNow: "", mytNow: "", request: {}, result_code: "", result_message: "" };
  if (!job) return Object.assign(base, { result_code: "PK_INVALID_DATA", result_message: "job " + guard.jobId + " not found" });
  if (s(job.command) !== "COMPLETE_PACKING") return Object.assign(base, { result_code: "PK_INVALID_DATA", result_message: "job command is " + s(job.command) });
  if (s(job.job_status) !== "VALIDATING") return Object.assign(base, { result_code: "JOB_ILLEGAL_TRANSITION", result_message: "job is " + s(job.job_status) + ": only a VALIDATING job is prepared" });
  if (String(job.lease_live) !== "1") return Object.assign(base, { result_code: "JOB_ROW_VERSION_CONFLICT", result_message: "the worker's lease on the job has expired: not prepared" });
  // the submitting user as the job row stores it (exact: {{system:uid}} reaches a code node as a number that loses digits)
  const common = { jobId: s(job.id), organizationId: s(job.organization_id), plantId: s(job.plant_id), requestedBy: s(job.create_user), rowVersion: Number(job.row_version) || 0, dbNow: s(job.db_now), mytNow: s(job.myt_now) };
  let req = null;
  try {
    req = JSON.parse(s(job.request_payload));
  } catch (e) {
    req = null;
  }
  const packingId = s(job.packing_id);
  const ok = req && typeof req === "object" && ID.test(packingId) && s(req.packing_id) === packingId && ID.test(s(req.gd_id)) && ID.test(common.plantId) && ID.test(common.organizationId);
  if (!ok) return Object.assign(base, common, { route: "FAIL", packingId: ID.test(packingId) ? packingId : "0", result_code: "PK_INVALID_REQUEST", result_message: "the job's request could not be read" });
  return Object.assign(base, common, { route: "GO", packingId: packingId, gdId: s(req.gd_id), request: req, result_message: "prepare Packing " + s(req.packing_no) });
};
const guard = [{{node:code_node_KPguard.data}}][0];
const res = prepareEntry(guard, [{{node:sql_node_KPjob.data}}][0]);
console.log("prepare entry", JSON.stringify({ route: res.route, packing: res.packingId, gd: res.gdId, result: res.result_code, message: res.result_message }));
return res;

// PACKING_BULK_PREPARE - Plan 1: the gates (code_node_PkPickChk, code_node_PkFullChk, the form's HU checks), the packed GD
// lines re-tagged to their HUs (code_node_nB1MhwgG) and the reservation moves (GD_UNUSED_FN_NEW detectBinHuMigrations, the
// packed lines only) -> the keys the second reads need; or the reason the Packing cannot be completed (FAILED, nothing written)
const planPacking1 = function planPacking1(entry, hdrRows, huRows, srcRows, husrcRows, gdRows, resRows, itemRows) {
  const s = (v) => (v === undefined || v === null ? "" : String(v)).trim();
  const list = (x) => (Array.isArray(x) ? x : x ? [x] : []).filter((r) => r);
  const num = (v) => parseFloat(v) || 0;
  const q8 = (v) => Number((parseFloat(v) || 0).toFixed(8));
  const raw = (v) => (v === undefined || v === null ? "" : String(v));
  const parse = (v, dflt) => {
    if (v === null || v === undefined || v === "") return dflt;
    if (typeof v !== "string") return v;
    try { return JSON.parse(v); } catch (e) { return dflt; }
  };
  const ID = /^[0-9]{1,20}$/;
  // id arrays as digit strings: JSON.parse rounds the 19-digit ids dev and prod store unquoted (goods_delivery.so_id, customer_id)
  const idsOf = (v) => (Array.isArray(v) ? v.join(",") : raw(v)).match(/[0-9]+/g) || [];
  const jobId = s(entry.jobId);
  const packingId = s(entry.packingId);
  const lockSession = "PKGJOB-" + jobId;
  const hdr = list(hdrRows).filter((r) => s(r.id))[0] || null;
  const base = { route: "FAIL", work: {}, jobRows: [], needJobUpd: "NO", unlockRows: [], needUnlock: "NO", result_code: "", result_message: "", job_status: "",
    itemTuplesSql: "(0,0)", batchTuplesSql: "(0,0,0)", binIdsSql: "0", batchIdsSql: "0", huIdsSql: "0", uomIdsSql: "0", soIdsJson: "[0]" };
  const fail = (code, message, details) => {
    const ours = !!hdr && s(hdr.packing_lock_session_id) === lockSession;
    return Object.assign({}, base, {
      jobRows: [{ id: jobId, job_status: "FAILED", progress_percent: 0, progress_message: ("Not completed: " + message).slice(0, 250), row_version: (Number(entry.rowVersion) || 0) + 1,
        error_code: code, error_message: message, error_details: JSON.stringify(Object.assign({ step: "PACKING_BULK_PREPARE" }, details || {})),
        lease_owner: null, lease_expires_at: null, finished_at: s(entry.dbNow) || null }],
      needJobUpd: "YES",
      unlockRows: ours ? [{ id: packingId, packing_lock_user_id: null, packing_lock_user_name: null, packing_lock_session_id: null, packing_lock_expires_at: null, packing_lock_updated_at: s(entry.mytNow) || null }] : [],
      needUnlock: ours ? "YES" : "NO",
      result_code: code, result_message: message, job_status: "FAILED",
    });
  };
  if (s(entry.route) === "FAIL") return fail(s(entry.result_code) || "PK_INVALID_REQUEST", s(entry.result_message) || "the request is not valid");

  if (!hdr || s(hdr.is_deleted) === "1") return fail("PK_NOT_FOUND", "Packing " + packingId + " was not found");
  const packingNo = s(hdr.packing_no);
  if (["Completed", "Cancelled"].indexOf(s(hdr.packing_status)) >= 0) return fail("PK_STATUS", "Packing " + packingNo + " is " + s(hdr.packing_status));
  const gdId = s(hdr.gd_found);
  if (!gdId) return fail("PK_NOT_SUPPORTED", "Packing " + packingNo + " has no Goods Delivery: press Save as Completed again to complete it the classic way");
  if (gdId !== s(entry.gdId)) return fail("PK_STALE", "Packing " + packingNo + " now belongs to another Goods Delivery");
  // code_node_PkPickChk: a cancelled delivery cannot be packed; only a Created one is re-tagged (GOODS_DELIVERY's Created re-save)
  if (s(hdr.gd_status) === "Cancelled") return fail("PK_GD_CLOSED", "Cannot complete packing: Goods Delivery " + s(hdr.delivery_no) + " is Cancelled.");
  if (s(hdr.gd_status) !== "Created") return fail("PK_GD_CLOSED", "Goods Delivery " + s(hdr.delivery_no) + " is " + (s(hdr.gd_status) || "not Created") + ": the Packing can only be completed while it is Created");
  if (s(hdr.gd_plant_id) !== s(entry.plantId) || s(hdr.gd_org) !== s(entry.organizationId)) return fail("PK_STALE", "Goods Delivery " + s(hdr.delivery_no) + " belongs to another plant or organization than the job");

  // ---- the picking gate, every GD line (bundle parents carry no material and are skipped)
  const gdLines = list(gdRows).filter((r) => s(r.id));
  const unpicked = [];
  for (const line of gdLines) {
    if (!s(line.material_id)) continue;
    if (s(line.picking_status) === "Cancelled") continue;
    if (num(line.gd_qty) <= 0) continue;
    if (s(line.picking_status) !== "Completed") unpicked.push((s(line.material_name) || s(line.material_id)) + " (" + (s(line.picking_status) || "Open") + ")");
  }
  if (unpicked.length) {
    return fail("PK_NOT_PICKED", "Cannot complete packing: these Goods Delivery lines are not fully picked - " + unpicked.slice(0, 3).join("; ") +
      (unpicked.length > 3 ? " (+" + (unpicked.length - 3) + " more)" : "") + ". Pickings still pending.");
  }

  // ---- the HUs as stored: every packed HU completed (the form checks this before it submits)
  const hus = list(huRows).filter((r) => s(r.id));
  const notDone = [];
  for (const r of hus) if (s(r.temp_data) && s(r.temp_data) !== "[]" && s(r.hu_status) !== "Completed") notDone.push("HU " + (s(r.handling_no) || "(unnumbered)") + " is not completed.");
  for (const r of list(husrcRows)) if (s(r.row_type) === "header" && s(r.hu_status) !== "Completed") notDone.push("Source HU " + (s(r.handling_no) || s(r.handling_unit_id) || "(?)") + " is not completed.");
  if (notDone.length) return fail("PK_HU_OPEN", "Cannot complete packing: " + notDone.slice(0, 3).join(" ") + (notDone.length > 3 ? " (+" + (notDone.length - 3) + " more)" : ""));

  // ---- the packed gate: table_hu temp_data against table_item_source (nested_hu children not flattened)
  const temp = hus.map((row) => ({ row: row, entries: list(parse(row.temp_data, [])) }));
  const packedByLine = {};
  for (const t of temp) {
    for (const e of t.entries) {
      if (!e || !e.line_item_id) continue;
      packedByLine[s(e.line_item_id)] = (packedByLine[s(e.line_item_id)] || 0) + num(e.total_quantity);
    }
  }
  const short = [];
  for (const r of list(srcRows)) {
    const label = s(r.item_name) || s(r.item_code) || s(r.id) || "(?)";
    const required = num(r.total_quantity);
    if (required <= 0) continue;
    if (!s(r.id)) {
      if (num(r.remaining_qty) > 0.001) short.push(label + ": " + num(r.remaining_qty) + " still unpacked");
      continue;
    }
    const packed = packedByLine[s(r.id)] || 0;
    if (Math.abs(required - packed) > 0.001) short.push(label + ": required " + required + ", packed " + packed);
  }
  if (short.length) {
    return fail("PK_NOT_PACKED", "Cannot complete packing — " + short.length + " line(s) not fully packed:\n" + short.slice(0, 10).join("\n") +
      (short.length > 10 ? "\n(+" + (short.length - 10) + " more)" : ""));
  }

  // ---- the GD lines the Packing names (code_node_BaPFkf1V: nested_hu children included) and their re-tag patches
  const named = {};
  const soLineIds = {};
  for (const t of temp) {
    for (const e of t.entries) {
      if (e && e.type === "nested_hu") {
        for (const c of list(e.children)) {
          if (s(c.gd_line_id)) named[s(c.gd_line_id)] = true;
          if (s(c.so_line_id)) soLineIds[s(c.so_line_id)] = true;
        }
      } else if (e) {
        if (s(e.gd_line_id)) named[s(e.gd_line_id)] = true;
        if (s(e.so_line_id)) soLineIds[s(e.so_line_id)] = true;
      }
    }
  }
  const patchesByLine = {};
  for (const t of temp) {
    const row = t.row;
    if (s(row.hu_row_type) === "locked") continue;
    const huId = s(row.handling_unit_id);
    const huBin = s(row.location_id);
    if (!huId || !huBin) continue;
    for (const e of t.entries) {
      if (!e || e.type === "nested_hu" || !e.gd_line_id) continue;
      (patchesByLine[s(e.gd_line_id)] = patchesByLine[s(e.gd_line_id)] || []).push({
        material_id: s(e.item_id), batch_id: s(e.batch_no), bin_location: s(e.bin_location), hu: huId, bin: huBin, remaining: num(e.total_quantity),
      });
    }
  }

  const items = {};
  for (const r of list(itemRows)) {
    const id = s(r.item_id);
    if (!id) continue;
    if (!items[id]) items[id] = { based: s(r.based_uom), batch: s(r.item_batch_management), serial: s(r.serial_number_management), method: s(r.material_costing_method),
      price: s(r.purchase_unit_price), stock: s(r.stock_control), conv: {} };
    if (s(r.alt_uom_id) && num(r.base_qty) > 0 && !(s(r.alt_uom_id) in items[id].conv)) items[id].conv[s(r.alt_uom_id)] = num(r.base_qty);
  }
  const lineById = {};
  for (const l of gdLines) lineById[s(l.id)] = l;

  const updates = [];
  const binIds = {};
  const batchIds = {};
  const huIds = {};
  const uomIds = {};
  for (const id of Object.keys(named).sort()) {
    const line = lineById[id];
    if (!line) continue;
    const originalTempQtyData = raw(line.temp_qty_data) || "[]";
    const originalTempHuData = raw(line.temp_hu_data) || "[]";
    if (s(line.gd_order_uom_id)) uomIds[s(line.gd_order_uom_id)] = true;
    const patches = patchesByLine[id] || [];
    // no patch still means packed: whole-HU (locked) rows were HU-tagged at pick time; the line is stamped as it is
    if (!patches.length) {
      updates.push({ id: id, temp_qty_data: originalTempQtyData, prev_temp_qty_data: originalTempQtyData, temp_hu_data: originalTempHuData, view_stock: raw(line.view_stock), packedHu: [], keep: 1, tqd: [] });
      continue;
    }
    const tqd = list(parse(originalTempQtyData, []));
    const packedHu = [];
    const updatedTqd = [];
    for (const entryRow of tqd) {
      if (entryRow.handling_unit_id && entryRow.handling_unit_id !== "") {
        updatedTqd.push(entryRow);
        continue;
      }
      const entryQty = parseFloat(entryRow.gd_quantity || 0);
      const matching = patches.filter((p) => p.material_id === s(entryRow.material_id) && p.batch_id === s(entryRow.batch_id) && p.bin_location === s(entryRow.location_id));
      if (!matching.length) {
        updatedTqd.push(entryRow);
        continue;
      }
      let left = entryQty;
      for (const p of matching) {
        if (p.remaining <= 0) continue;
        if (left <= 0) break;
        const claim = Math.min(left, p.remaining);
        if (claim <= 0) continue;
        updatedTqd.push(Object.assign({}, entryRow, { handling_unit_id: p.hu, location_id: p.bin, gd_quantity: claim }));
        packedHu.push({ handling_unit_id: p.hu, material_id: entryRow.material_id, location_id: p.bin, batch_id: entryRow.batch_id || null, balance_id: entryRow.balance_id || "", qty: claim });
        left = q8(left - claim);
        p.remaining = q8(p.remaining - claim);
      }
      if (left > 0) updatedTqd.push(Object.assign({}, entryRow, { gd_quantity: left }));
    }
    for (const e of updatedTqd) {
      if (s(e.location_id)) binIds[s(e.location_id)] = true;
      if (s(e.batch_id)) batchIds[s(e.batch_id)] = true;
      if (s(e.handling_unit_id)) huIds[s(e.handling_unit_id)] = true;
    }
    for (const h of packedHu) huIds[s(h.handling_unit_id)] = true;
    // prev = the re-tagged value: the classic path's GD re-save (whose move V2 makes itself) ends with prev = current
    updates.push({ id: id, temp_qty_data: JSON.stringify(updatedTqd), prev_temp_qty_data: JSON.stringify(updatedTqd), temp_hu_data: originalTempHuData, view_stock: raw(line.view_stock), packedHu: packedHu, keep: 0, tqd: updatedTqd });
  }

  // ---- the reservation moves (detectBinHuMigrations), over the re-tagged lines only
  const restate = (rec, line) => {
    const lineUom = s(line.gd_order_uom_id) || s(line.good_delivery_uom_id);
    if (!lineUom || !s(rec.item_uom) || s(rec.item_uom) === lineUom) return;
    const it = items[s(rec.material_id) || s(line.material_id)];
    const factor = (u) => (!it || !u ? 0 : u === it.based ? 1 : it.conv[u] || 0);
    const from = factor(s(rec.item_uom));
    const to = factor(lineUom);
    if (!from || !to) return;
    const ratio = from / to;
    rec.reserved_qty = q8(num(rec.reserved_qty) * ratio);
    rec.open_qty = q8(num(rec.open_qty) * ratio);
    rec.delivered_qty = q8(num(rec.delivered_qty) * ratio);
    rec.item_uom = lineUom;
  };
  const allocated = list(resRows).filter((r) => s(r.id) && s(r.status) === "Allocated" && s(r.target_gd_id) === gdId)
    .map((r) => Object.assign({}, r, { reserved_qty: num(r.reserved_qty), open_qty: num(r.open_qty), delivered_qty: num(r.delivered_qty) }));
  const snapRes = {};
  for (const r of allocated) snapRes[s(r.id)] = [s(r.id), q8(r.reserved_qty), q8(r.open_qty), s(r.status), s(r.bin_location), s(r.handling_unit_id)];
  for (const r of allocated) if (lineById[s(r.doc_line_id)]) restate(r, lineById[s(r.doc_line_id)]);

  const moved = {};
  for (const u of updates) if (!u.keep) moved[u.id] = u;
  const oldByTriplet = new Map();
  for (const rec of allocated) {
    if (!moved[s(rec.doc_line_id)]) continue;
    const k = s(rec.doc_line_id) + "|" + s(rec.material_id) + "|" + s(rec.batch_id);
    if (!oldByTriplet.has(k)) oldByTriplet.set(k, []);
    oldByTriplet.get(k).push(rec);
  }
  // the line's entries grouped as GD_UNUSED_FN_NEW's batch fetch groups them (by batch only for a batch-managed item)
  const newByTriplet = new Map();
  for (const id of Object.keys(moved)) {
    const line = lineById[id];
    const batchItem = Number((items[s(line.material_id)] || {}).batch) === 1;
    const groups = {};
    const order = [];
    for (const t of moved[id].tqd) {
      let gk = batchItem && t.batch_id ? t.location_id + "|" + t.batch_id : String(t.location_id);
      if (t.handling_unit_id) gk += "|hu-" + t.handling_unit_id;
      if (!groups[gk]) {
        groups[gk] = { location_id: t.location_id, batch_id: t.batch_id || null, handling_unit_id: t.handling_unit_id || null, totalQty: 0 };
        order.push(gk);
      }
      groups[gk].totalQty += parseFloat(t.gd_quantity || t.to_quantity || t.quantity || 0);
    }
    for (const gk of order) {
      const g = groups[gk];
      const k = id + "|" + s(line.material_id) + "|" + s(g.batch_id);
      if (!newByTriplet.has(k)) newByTriplet.set(k, []);
      newByTriplet.get(k).push({ group: g, binLocation: s(g.location_id), handlingUnitId: s(g.handling_unit_id) });
    }
  }

  const resUpdates = new Map();
  const resCreates = [];
  const chunks = [];
  const uncovered = [];
  for (const [tripletKey, oldRecs] of oldByTriplet) {
    const newEntries = newByTriplet.get(tripletKey) || [];
    if (!newEntries.length) continue;
    const tupleMatch = (r, e) => s(r.bin_location) === e.binLocation && s(r.handling_unit_id) === e.handlingUnitId;
    const liveNew = newEntries.filter((e) => q8(e.group.totalQty || 0) > 0);
    const unmatchedNew = liveNew.filter((e) => !oldRecs.some((r) => tupleMatch(r, e)));
    if (!unmatchedNew.length) continue;
    const tupleKey = (bin, hu) => s(bin) + "|" + s(hu);
    const newAtTuple = new Map();
    for (const e of liveNew) newAtTuple.set(tupleKey(e.binLocation, e.handlingUnitId), q8((newAtTuple.get(tupleKey(e.binLocation, e.handlingUnitId)) || 0) + q8(e.group.totalQty || 0)));
    const oldAtTuple = new Map();
    for (const r of oldRecs) {
      const k = tupleKey(r.bin_location, r.handling_unit_id);
      if (!oldAtTuple.has(k)) oldAtTuple.set(k, []);
      oldAtTuple.get(k).push(r);
    }
    const migratable = new Map();
    const unmatchedOld = [];
    const surplusOld = [];
    for (const [k, recs] of oldAtTuple) {
      const held = newAtTuple.get(k) || 0;
      let surplus = q8(recs.reduce((sum, r) => sum + q8(r.reserved_qty || 0), 0) - held);
      for (const r of recs) {
        if (surplus <= 0) break;
        const give = q8(Math.min(q8(r.reserved_qty || 0), surplus));
        if (give <= 0) continue;
        migratable.set(r, give);
        (held > 0 ? surplusOld : unmatchedOld).push(r);
        surplus = q8(surplus - give);
      }
    }
    const newRemaining = new Map();
    for (const e of unmatchedNew) newRemaining.set(e, q8(e.group.totalQty || 0));
    for (const oldRec of unmatchedOld.concat(surplusOld)) {
      let oldRemaining = migratable.get(oldRec) || 0;
      for (const e of unmatchedNew) {
        if (oldRemaining <= 0) break;
        const avail = newRemaining.get(e) || 0;
        if (avail <= 0) continue;
        const qty = q8(Math.min(oldRemaining, avail));
        if (qty <= 0) continue;
        const left = q8((oldRec.reserved_qty || 0) - qty);
        // as GD_UNUSED_FN_NEW's update writes them: a cancelled row's other columns are written empty
        if (left <= 0) {
          resUpdates.set(s(oldRec.id), { id: s(oldRec.id), target_gd_id: null, status: "Cancelled", reserved_qty: oldRec.reserved_qty, open_qty: 0, delivered_qty: null,
            doc_no: null, doc_id: null, doc_line_id: null, source_reserved_id: null, item_uom: null });
        } else {
          resUpdates.set(s(oldRec.id), { id: s(oldRec.id), target_gd_id: s(oldRec.target_gd_id), status: s(oldRec.status), reserved_qty: left, open_qty: left, delivered_qty: oldRec.delivered_qty,
            doc_no: s(oldRec.doc_no), doc_id: s(oldRec.doc_id), doc_line_id: s(oldRec.doc_line_id), source_reserved_id: s(oldRec.source_reserved_id), item_uom: s(oldRec.item_uom) });
          oldRec.reserved_qty = left;
          oldRec.open_qty = left;
        }
        const seq = chunks.length + 1;
        resCreates.push({
          job_line_key: jobId + "|" + s(oldRec.id) + "|" + seq,
          doc_type: s(oldRec.doc_type), status: "Allocated", parent_id: s(oldRec.parent_id), parent_line_id: s(oldRec.parent_line_id), parent_no: s(oldRec.parent_no),
